mapper.select:
WITH raw_data AS ( SELECT rd.tagname, rd.ts, rd.value, pti.CLSFC, pti.PWI_UNIT_VALUE FROM TB_RAWDATA rd JOIN TB_PEAK_TAG_INF pti ON rd.tagname = pti.PWI_TAG WHERE pti.MNTR_YN = '1' AND pti.IS_ALL = '1' AND pti.CLSFC IS NOT NULL AND pti.CLSFC != '' AND rd.ts >= DATE_FORMAT(now(), '%Y-%m-%d 00:00:00') AND rd.ts <= DATE_FORMAT(now(), '%Y-%m-%d 23:59:59')
AND pti.CLSFC = #{zone_code}
), diff_data AS ( SELECT tagname, ts, CLSFC, ROUND(value * PWI_UNIT_VALUE, 6) AS y FROM raw_data ) SELECT DATE_FORMAT(ts, '%Y-%m-%d %H:%i') AS x, CLSFC AS zone_name, ROUND(SUM(y), 2) AS y FROM diff_data WHERE ts >= DATE_FORMAT(now(), '%Y-%m-%d 00:00:00') AND ts <= DATE_FORMAT(now(), '%Y-%m-%d 23:59:59') GROUP BY ts, CLSFC ORDER BY zone_name, ts
